import AVFoundation
import SwiftUI

/// Menu music and interface sounds (original audio, generated by ios/tools/synth_sounds.py).
@MainActor
final class SoundManager: ObservableObject {
    static let shared = SoundManager()

    enum Effect: String, CaseIterable {
        case tap = "ui_tap", select = "ui_select", back = "ui_back", toggle = "ui_toggle"
        case open = "ui_open", launch = "ui_launch", error = "ui_error"
    }

    @Published var musicEnabled: Bool = UserDefaults.standard.object(forKey: "musicEnabled") as? Bool ?? true {
        didSet { UserDefaults.standard.set(musicEnabled, forKey: "musicEnabled"); musicEnabled ? startMusic() : stopMusic() }
    }
    @Published var effectsEnabled: Bool = UserDefaults.standard.object(forKey: "effectsEnabled") as? Bool ?? true {
        didSet { UserDefaults.standard.set(effectsEnabled, forKey: "effectsEnabled") }
    }
    @Published var musicVolume: Double = UserDefaults.standard.object(forKey: "musicVolume") as? Double ?? 0.45 {
        didSet { UserDefaults.standard.set(musicVolume, forKey: "musicVolume"); musicNode.volume = Float(musicVolume) }
    }
    @Published var effectsVolume: Double = UserDefaults.standard.object(forKey: "effectsVolume") as? Double ?? 0.7 {
        didSet { UserDefaults.standard.set(effectsVolume, forKey: "effectsVolume") }
    }

    private let engine = AVAudioEngine()
    private let musicNode = AVAudioPlayerNode()
    private var effectNodes: [AVAudioPlayerNode] = []
    private var nextEffectNode = 0
    private var buffers: [Effect: AVAudioPCMBuffer] = [:]
    private var musicBuffer: AVAudioPCMBuffer?
    private var prepared = false
    private var musicPlaying = false
    private var suspended = false // while a game runs
    private var lastEffectTime: [Effect: CFTimeInterval] = [:]

    private init() {
        NotificationCenter.default.addObserver(forName: AVAudioSession.interruptionNotification, object: nil, queue: .main) { [weak self] note in
            guard let raw = note.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt,
                  AVAudioSession.InterruptionType(rawValue: raw) == .ended else { return }
            Task { @MainActor in self?.restartAfterInterruption() }
        }
    }

    private func prepare() {
        guard !prepared else { return }
        prepared = true
        let dir = Bundle.main.bundleURL.appendingPathComponent("Sounds")
        musicBuffer = Self.loadBuffer(dir.appendingPathComponent("menu_music.caf"))
        for e in Effect.allCases {
            buffers[e] = Self.loadBuffer(dir.appendingPathComponent("\(e.rawValue).wav"))
        }
        engine.attach(musicNode)
        let musicFormat = musicBuffer?.format ?? engine.mainMixerNode.outputFormat(forBus: 0)
        engine.connect(musicNode, to: engine.mainMixerNode, format: musicFormat)
        musicNode.volume = Float(musicVolume)
        let fxFormat = buffers[.tap]?.format ?? musicFormat
        for _ in 0..<4 {
            let n = AVAudioPlayerNode()
            engine.attach(n)
            engine.connect(n, to: engine.mainMixerNode, format: fxFormat)
            effectNodes.append(n)
        }
        engine.prepare()
    }

    private static func loadBuffer(_ url: URL) -> AVAudioPCMBuffer? {
        guard let file = try? AVAudioFile(forReading: url),
              let buf = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(file.length)) else { return nil }
        try? file.read(into: buf)
        return buf
    }

    private func ensureRunning() -> Bool {
        prepare()
        if !engine.isRunning {
            do { try engine.start() } catch { return false }
        }
        return true
    }

    // MARK: music

    func startMusic() {
        guard musicEnabled, !suspended, !musicPlaying, ensureRunning(), let musicBuffer else { return }
        musicNode.stop()
        musicNode.volume = 0
        musicNode.scheduleBuffer(musicBuffer, at: nil, options: .loops)
        musicNode.play()
        musicPlaying = true
        fade(to: Float(musicVolume), duration: 1.2)
    }

    func stopMusic(fadeOut: Double = 0.6) {
        guard musicPlaying else { return }
        musicPlaying = false
        fade(to: 0, duration: fadeOut) { [weak self] in
            guard let self, !self.musicPlaying else { return }
            self.musicNode.stop()
        }
    }

    private var fadeTask: Task<Void, Never>?
    private func fade(to target: Float, duration: Double, completion: (() -> Void)? = nil) {
        fadeTask?.cancel()
        let start = musicNode.volume
        let steps = max(Int(duration * 30), 1)
        fadeTask = Task { @MainActor [weak self] in
            for i in 1...steps {
                try? await Task.sleep(nanoseconds: UInt64(duration / Double(steps) * 1_000_000_000))
                if Task.isCancelled { return }
                self?.musicNode.volume = start + (target - start) * Float(i) / Float(steps)
            }
            completion?()
        }
    }

    /// Called when a game starts: menu audio goes quiet so only the game is heard.
    func suspendForGame() {
        suspended = true
        stopMusic(fadeOut: 0.8)
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 1_900_000_000)
            if self.suspended { self.engine.pause() }
        }
    }

    /// App went to the background: stop the engine so the audio background mode doesn't keep it alive.
    func enterBackground() {
        stopMusic(fadeOut: 0.05)
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 200_000_000)
            if !self.musicPlaying { self.engine.pause() }
        }
    }

    func resumeAfterGame() {
        suspended = false
        startMusic()
    }

    private func restartAfterInterruption() {
        guard !suspended else { return }
        musicPlaying = false
        startMusic()
    }

    // MARK: effects

    func play(_ effect: Effect) {
        guard effectsEnabled else { return }
        prepare()
        guard let buf = buffers[effect] else { return }
        let now = CACurrentMediaTime()
        if let last = lastEffectTime[effect], now - last < 0.04 { return }
        lastEffectTime[effect] = now
        guard ensureRunning(), !effectNodes.isEmpty else { return }
        let node = effectNodes[nextEffectNode]
        nextEffectNode = (nextEffectNode + 1) % effectNodes.count
        node.stop()
        node.volume = Float(effectsVolume)
        node.scheduleBuffer(buf, at: nil)
        node.play()
    }
}

// MARK: - SwiftUI helpers

extension View {
    /// Plays an interface sound when the view is tapped, without taking over its own action.
    func sound(_ effect: SoundManager.Effect) -> some View {
        simultaneousGesture(TapGesture().onEnded { SoundManager.shared.play(effect) })
    }
}

/// Button that plays a sound and a light haptic.
struct SoundButton<Label: View>: View {
    var effect: SoundManager.Effect = .select
    var role: ButtonRole? = nil
    let action: () -> Void
    @ViewBuilder var label: Label

    var body: some View {
        Button(role: role) {
            SoundManager.shared.play(effect)
            Haptics.tap()
            action()
        } label: { label }
    }
}

/// Small press-down scale for cards.
struct PressableStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .scaleEffect(configuration.isPressed ? 0.95 : 1)
            .brightness(configuration.isPressed ? -0.04 : 0)
            .animation(.spring(response: 0.25, dampingFraction: 0.7), value: configuration.isPressed)
    }
}
